-- RBAC #73: parallel generation. One object per execution step.
-- No serving switch or old-object drop in this build.
-- Production: reviewed DDL window, fresh capacity/watch baseline, clean checkout.
-- Before next object: rw_ddl_progress empty, this object catalog-visible,
-- direct dependencies bind, receipt records artifact SHA and Git commit.
SET BACKGROUND_DDL = true;
SET STREAMING_PARALLELISM = 1;
SET backfill_rate_limit = 1000;

CREATE MATERIALIZED VIEW rw_inbox_serving_jcm_v1 AS SELECT p.server_id, p.receiver_type, p.receiver_id, CASE WHEN p.kind = 'thread' AND c.type = 'task' THEN 'task' ELSE p.kind END AS kind, CASE WHEN p.kind = 'thread' THEN NULL ELSE p.target_id END AS channel_id, CASE WHEN p.kind = 'thread' THEN NULL ELSE c.name END AS channel_name, CASE WHEN p.kind = 'thread' THEN NULL ELSE c.type END AS channel_type, lm.id AS last_message_id, CASE WHEN c.type = 'task' THEN tfu.id ELSE fu.id END AS first_unread_message_id, CASE WHEN p.kind = 'thread' THEN NULL ELSE COALESCE(lm.created_at, p.latest_at) END AS last_message_at, CASE WHEN p.kind = 'thread' THEN NULL ELSE lm.preview END AS last_message_preview, CASE WHEN p.kind = 'thread' THEN NULL ELSE lm.sender_type END AS last_message_sender_type, CASE WHEN p.kind = 'thread' THEN NULL ELSE lm.sender_id END AS last_message_sender_id, CAST(COALESCE(CASE WHEN c.type = 'task' THEN tu.unread_count ELSE p.unread_count END, 0) AS INT) AS unread_count, CASE WHEN p.kind = 'thread' THEN p.target_id ELSE NULL END AS thread_channel_id, tp.parent_message_id, tp.parent_channel_id, tp.parent_channel_name, tp.parent_channel_type, pm.preview AS parent_message_preview, pm.sender_type AS parent_message_sender_type, pm.sender_id AS parent_message_sender_id, COALESCE(lm.preview, ma.preview) AS latest_activity_preview, COALESCE(lm.sender_type, ma.sender_type) AS latest_activity_sender_type, COALESCE(lm.sender_id, ma.sender_id) AS latest_activity_sender_id, COALESCE(lm.id, ma.id) AS latest_activity_message_id, COALESCE(lm.seq, ma.seq) AS latest_activity_seq, COALESCE(lm.created_at, p.latest_at) AS last_activity_at, CASE WHEN p.kind = 'thread' THEN COALESCE(lm.created_at, p.latest_at) ELSE NULL END AS last_reply_at, CASE WHEN p.kind = 'thread' THEN CASE WHEN c.type = 'task' THEN CAST(COALESCE(tr.reply_count, 0) AS INT) ELSE CAST(tl.msg_count AS INT) END ELSE NULL END AS reply_count, COALESCE(ctk.task_number, tk.task_number) AS task_number, COALESCE(ctk.status, tk.status) AS task_status, COALESCE(ctk.claimed_by_type, tk.claimed_by_type) AS task_claimed_by_type, COALESCE(ctk.claimed_by_id, tk.claimed_by_id) AS task_claimed_by_id, (p.mention_unread > 0) AS has_mention, (p.mention_unread > 0 AND p.unread_count IS NULL) AS mention_only, CAST(p.last_read_seq AS BIGINT) AS last_read_seq, COALESCE(lm.created_at, p.latest_at, ma.created_at) AS activity_at, (p.total_mentions > 0) AS has_any_mention, CASE WHEN p.mention_unread > 0 AND p.unread_count IS NULL THEN NULL ELSE p.first_mention_message_id END AS first_mention_message_id, CAST(p.mention_done_through_seq AS BIGINT) AS mention_done_through_seq FROM rw_inbox_items_jcm_v1 AS p LEFT JOIN rw_activity_watermark_jcm_v1 AS w ON w.receiver_type = p.receiver_type AND w.receiver_id = p.receiver_id AND w.server_id = p.server_id LEFT JOIN rw_channels AS c ON c.id = p.target_id LEFT JOIN rw_inbox_preview_seq_jcm_v1 AS lm ON lm.seq = p.latest_seq LEFT JOIN rw_inbox_preview_seq_jcm_v1 AS fu ON fu.seq = p.first_unread_seq LEFT JOIN rw_conversation_parent_v1 AS tp ON tp.thread_channel_id = p.target_id AND p.kind = 'thread' LEFT JOIN rw_inbox_preview_parent_v1 AS pm ON pm.id = tp.parent_message_id LEFT JOIN rw_tasks AS tk ON tk.message_id = tp.parent_message_id LEFT JOIN rw_tasks AS ctk ON ctk.id = tp.task_id LEFT JOIN rw_target_latest_v4 AS tl ON tl.target_id = p.target_id LEFT JOIN rw_task_conversation_replies_v1 AS tr ON tr.target_id = p.target_id LEFT JOIN rw_task_conversation_unread_jcm_v1 AS tu ON tu.receiver_type = p.receiver_type AND tu.receiver_id = p.receiver_id AND tu.target_id = p.target_id LEFT JOIN rw_inbox_preview_seq_jcm_v1 AS tfu ON tfu.seq = tu.first_unread_seq LEFT JOIN rw_inbox_preview_seq_jcm_v1 AS ma ON ma.seq = p.max_mention_seq WHERE p.present AND GREATEST(COALESCE(tl.latest_seq, 0), COALESCE(p.latest_seq, 0), COALESCE(p.max_mention_seq, 0)) >= COALESCE(w.watermark_seq, 0);
